// fib(n) returns the n-th Fibonacci number (fib(0) = 0, fib(1) = 1)
// It must be fast for n up to 90.
pub fn fib(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1) + fib(n - 2),
    }
}

