/// Run-length encodes a string.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
pub fn rle(input: &str) -> String {
    input.chars()
        .fold(String::new(), |acc, c| {
            acc + format!("{}{}", acc.chars().count(), c)
        })
}

