/// Returns every prime number less than or equal to n, in increasing order.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(primes_up_to(10), vec![2, 3, 5, 7]);
/// assert_eq!(primes_up_to(1), vec![]);
/// assert_eq!(primes_up_to(2), vec![2]);
/// ```
fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes = Vec::new();
    for i in 2..=n {
        if is_prime(i) {
            primes.push(i);
        }
    }
    primes
}

/// Checks if a number is prime.
fn is_prime(n: u32) -> bool {
    if n <= 1 {
        return false;
    }
    for i in 2..=((n as f64).sqrt() as u32) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

// A simple check function to verify the correctness of the `primes_up_to` function.
fn check() {
    assert_eq!(primes_up_to(10), vec![2, 3, 5, 7]);
    assert_eq!(primes_up_to(1), vec![]);
    assert_eq!(primes_up_to(2), vec![2]);
    println!("All tests passed!");
}

