/// Reverses the order of words in the input string `s`.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words("hello world"), "world hello");
/// assert_eq!(reverse_words("  leading spaces"), "spaces leading");
/// assert_eq!(reverse_words("trailing spaces  "), "spaces trailing");
/// assert_eq!(reverse_words("  multiple   spaces  "), "spaces multiple   ");
/// ```
pub fn reverse_words(s: &str) -> String {
    s.split_whitespace()
        .rev()
        .collect::<Vec<&str>>()
        .join(" ")
}

// Check function to verify the correctness of the `reverse_words` function
fn check() {
    assert_eq!(reverse_words("hello world"), "world hello");
    assert_eq!(reverse_words("  leading spaces"), "spaces leading");
    assert_eq!(reverse_words("trailing spaces  "), "spaces trailing");
    assert_eq!(reverse_words("  multiple   spaces  "), "spaces multiple   ");
    println!("All tests passed!");
}

