/// Determines if two strings are anagrams of each other, ignoring case and spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(is_anagram("listen", "silent"), true);
/// assert_eq!(is_anagram("Hello", "World"), false);
/// assert_eq!(is_anagram("Dormitory", "Dirty room"), true);
/// assert_eq!(is_anagram("Conversation", "Voices rant on"), true);
/// assert_eq!(is_anagram("School master", "The classroom"), true);
/// assert_eq!(is_anagram("Astronomer", "Moon starer"), true);
/// assert_eq!(is_anagram("School master", "The classroom!"), false);
/// ```
fn is_anagram(a: &str, b: &str) -> bool {
    let a_chars: Vec<char> = a.chars().filter(|&c| !c.is_whitespace()).collect();
    let b_chars: Vec<char> = b.chars().filter(|&c| !c.is_whitespace()).collect();

    a_chars.iter().filter(|&c| c.is_lowercase()).count() == b_chars.iter().filter(|&c| c.is_lowercase()).count()
}

