/// Generates a vector of strings for numbers 1 to n, where:
/// - "Fizz" is added for multiples of 3.
/// - "Buzz" is added for multiples of 5.
/// - "FizzBuzz" is added for multiples of both 3 and 5.
/// - The number itself is added otherwise.
///
/// # Examples
/// ```
/// assert_eq!(fizzbuzz(1), vec![String::from("1")]);
/// assert_eq!(fizzbuzz(3), vec![String::from("1"), String::from("2"), String::from("Fizz")]);
/// assert_eq!(fizzbuzz(5), vec![String::from("1"), String::from("2"), String::from("Fizz"), String::from("4"), String::from("Buzz")]);
/// assert_eq!(fizzbuzz(15), vec![String::from("1"), String::from("2"), String::from("Fizz"), String::from("4"), String::from("Buzz"), String::from("Fizz"), String::from("15")]);
/// ```
pub fn fizzbuzz(n: u32) -> Vec<String> {
    (1..=n)
        .map(|i| {
            if i % 3 == 0 && i % 5 == 0 {
                "FizzBuzz".to_string()
            } else if i % 3 == 0 {
                "Fizz".to_string()
            } else if i % 5 == 0 {
                "Buzz".to_string()
            } else {
                i.to_string()
            }
        })
        .collect()
}

// A simple check function to verify the correctness of the `fizzbuzz` function.
fn check() {
    assert_eq!(fizzbuzz(1), vec![String::from("1")]);
    assert_eq!(fizzbuzz(3), vec![String::from("1"), String::from("2"), String::from("Fizz")]);
    assert_eq!(fizzbuzz(5), vec![String::from("1"), String::from("2"), String::from("Fizz"), String::from("4"), String::from("Buzz")]);
