/// Finds the maximum sum of a contiguous subarray within a given slice of integers.
///
/// # Examples
///
/// ```
/// assert_eq!(max_subarray(&[]), 0);
/// assert_eq!(max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]), 6);
/// ```
///
/// # Arguments
///
/// * `v` - A slice of integers.
///
/// # Returns
///
/// The maximum sum of a contiguous subarray.
fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }

    let mut max_so_far = v[0];
    let mut current_max = v[0];

    for &num in v.iter().skip(1) {
        current_max = std::cmp::max(num, current_max + num);
        max_so_far = std::cmp::max(max_so_far, current_max);
    }

    max_so_far
}

// Check function to verify the correctness of the generated function.
fn check() {
    assert_eq!(max_subarray(&[]), 0);
    assert_eq!(max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]), 6);
    assert_eq!(max_subarray(&[1, 2, 3, 4]), 10);
    assert_eq!(max_subarray(&[-1, -2, -3, -4]), -1);
    assert_eq!(max_subarray(&[0, 0, 0, 0]), 0);
    println!("All tests passed!");
}

