pub fn from_roman(s: &str) -> Option<u32> {
    let mut result = 0;
    let mut prev_value = 0;

    for c in s.chars() {
        match c {
            'I' => result += 1,
            'V' => result += 5,
            'X' => result += 10,
            'L' => result += 50,
            'C' => result += 100,
            'D' => result += 500,
            'M' => result += 1000,
            _ => return None,
        }

        if prev_value < result {
            result -= 2 * prev_value;
        }

        prev_value = result;
    }

    Some(result)
}

