/// Removes consecutive repeated values from a slice, keeping the first of each run.
///
/// # Examples
///
/// ```
/// assert_eq!(dedup(&[1, 1, 2, 3, 3, 4]), vec![1, 2, 3, 4]);
/// assert_eq!(dedup(&[5, 5, 5, 5]), vec![5]);
/// assert_eq!(dedup(&[]), Vec::<i32>::new());
/// ```
pub fn dedup(v: &[i32]) -> Vec<i32> {
    v.iter()
        .enumerate()
        .filter(|(_, &prev)| prev != v[next])
        .map(|(_, &val)| val)
        .collect()
}

