/// Merges two sorted slices into one sorted vector.
///
/// # Examples
///
/// ```
/// assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
/// assert_eq!(merge_sorted(&[], &[1, 2, 3]), vec![1, 2, 3]);
/// assert_eq!(merge_sorted(&[1, 2, 3], &[]), vec![1, 2, 3]);
/// assert_eq!(merge_sorted(&[10, 20], &[]), vec![10, 20]);
/// ```
pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut merged = Vec::with_capacity(a.len() + b.len());
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            merged.push(a[i]);
            i += 1;
        } else {
            merged.push(b[j]);
            j += 1;
        }
    }

    // Append remaining elements from either slice
    merged.extend(a.iter().skip(i));
    merged.extend(b.iter().skip(j));

    merged
}

// Check function to verify the correctness of the merge_sorted function
fn check() {
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[], &[1, 2, 3]), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&[1, 2, 3], &[]), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&[10, 20], &[]), vec![10, 20]);
    println!("All tests passed!");
}

