pub fn is_balanced(s: &str) -> bool {
    let mut stack = Vec::new();

    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' => {
                if stack.is_empty() || stack.pop() != '(' {
                    return false;
                }
            },
            ']' => {
                if stack.is_empty() || stack.pop() != '[' {
                    return false;
                }
            },
            '}' => {
                if stack.is_empty() || stack.pop() != '{' {
                    return false;
                }
            },
            _ => {}
        }
    }

    stack.is_empty()
}

