/// Calculates the median of a slice of f64 values.
///
/// # Examples
///
/// ```
/// assert_eq!(median(&[]), None);
/// assert_eq!(median(&[1.0]), Some(1.0));
/// assert_eq!(median(&[2.0, 1.0]), Some(1.5));
/// assert_eq!(median(&[3.0, 2.0, 1.0]), Some(2.0));
/// ```
pub fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut sorted = v.to_vec();
    sorted.sort_unstable();

    if sorted.len() % 2 == 0 {
        Some((sorted[sorted.len() / 2 - 1] + sorted[sorted.len() / 2]) / 2.0)
    } else {
        Some(sorted[sorted.len() / 2])
    }
}

