pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 7 && s.len() != 9 {
        return None;
    }

    let mut rgb = [0; 3];
    for (i, c) in s.chars().enumerate() {
        if i % 2 == 0 {
            if !c.is_ascii_digit() && !c == 'A' && !c == 'a' && !c == 'F' {
                return None;
            }
            let digit = c.to_digit(16).unwrap();
            rgb[i / 2] = digit;
        } else {
            if !c.is_ascii_digit() && !c == '0' && !c == '1' && !c == '2' && !c == '3' && !c == '4' && !c == '5' && !c == '6' && !c == '7' {
                return None;
            }
            let digit = c.to_digit(16).unwrap();
            rgb[i / 2] = digit * 16;
        }
    }

    Some((rgb[0], rgb[1], rgb[2]))
}

