/// Returns the second largest distinct value in a slice, or None if there are fewer than two distinct values.
///
/// # Examples
///
/// ```
/// assert_eq!(second_largest(&[]), None);
/// assert_eq!(second_largest(&[1]), None);
/// assert_eq!(second_largest(&[1, 1]), None);
/// assert_eq!(second_largest(&[1, 2, 3]), Some(2));
/// assert_eq!(second_largest(&[3, 2, 1]), Some(2));
/// assert_eq!(second_largest(&[5, 5, 4, 4, 3, 3]), Some(4));
/// ```
pub fn second_largest(v: &[i32]) -> Option<i32> {
    let mut unique_values: Vec<i32> = v.iter().filter_uniq().cloned().collect();
    if unique_values.len() < 2 {
        return None;
    }
    unique_values.sort_unstable();
    Some(unique_values[unique_values.len() - 2])
}

