/// Rotates the slice `v` to the left by `k` positions.
/// If `k` is greater than the length of `v`, the slice is rotated
/// as many times as needed to fit within the length of `v`.
///
/// # Examples
///
/// ```
/// assert_eq!(rotate_left(&[1, 2, 3, 4, 5], 2), vec![3, 4, 5, 1, 2]);
/// assert_eq!(rotate_left(&[1, 2, 3, 4, 5], 7), vec![3, 4, 5, 1, 2]);
/// assert_eq!(rotate_left(&[], 3), vec![]);
/// ```
pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    let len = v.len();
    let k = k % len; // Handle cases where k > len
    let rotated = v[k..] // Slice from k to the end
        .iter()
        .chain(v[..k].iter()) // Concatenate the two slices
        .cloned()
        .collect();
    rotated
}

// Check function to verify the correctness of the rotate_left function
fn check() {
    assert_eq!(rotate_left(&[1, 2, 3, 4, 5], 2), vec![3, 4, 5, 1, 2]);
    assert_eq!(rotate_left(&[1, 2, 3, 4, 5], 7), vec![3, 4, 5, 1, 2]);
    assert_eq!(rotate_left(&[], 3), vec![]);
    println!("All tests passed!");
}

