use std::collections::HashMap;

/// Parses a string into a HashMap of key-value pairs.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a".to_string(), "1".to_string()), ("b".to_string(), "two".to_string())]));
/// assert_eq!(parse_kv("a=1;"), HashMap::from([("a".to_string(), "1".to_string())]));
/// assert_eq!(parse_kv("a;"), HashMap::from([]));
/// assert_eq!(parse_kv("a=1;b=2;c=3"), HashMap::from([("a".to_string(), "1".to_string()), ("b".to_string(), "2".to_string()), ("c".to_string(), "3".to_string())]));
/// ```
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';')
        .filter_map(|pair| {
            let mut parts = pair.split('=');
            let key = parts.next().and_then(|s| s.parse::<String>().ok())?;
            let value = parts.next().and_then(|s| s.parse::<String>().ok())?;
            Some((key, value))
        })
        .collect()
}

